DO $preflight$
DECLARE target record;
BEGIN
  FOR target IN SELECT * FROM (VALUES
    ('model_capacity_requests','model_capacity_requests_logical_check'),
    ('model_capacity_requests','model_capacity_requests_members_check'),
    ('model_capacity_requests','model_capacity_requests_dispatch_check'),
    ('model_capacity_requests','model_capacity_requests_terminal_check'),
    ('model_capacity_events','model_capacity_events_terminal_check')
  ) AS expected(table_name,constraint_name) LOOP
    IF NOT EXISTS (SELECT 1 FROM model_capacity_check_rules r
      WHERE r.table_name=target.table_name AND r.constraint_name=target.constraint_name AND r.source='0160_ledger_check_rules') THEN
      RAISE EXCEPTION 'japanese_translation_rule_baseline_missing: %',target.constraint_name;
    END IF;
  END LOOP;
END $preflight$;
